/** Render, hand back the tree and a finder, unmount when the caller is done. */
function mount(el: React.ReactElement) {
  let tree!: renderer.ReactTestRenderer;
  act(() => { tree = renderer.create(el); });
  const json = JSON.stringify(tree.toJSON());
  const press = (testID: string) => {
    const node = tree.root.findAll(
      (n) => n.props?.testID === testID && typeof n.props?.onPress === 'function',
      { deep: true },
    )[0];
    if (!node) throw new Error(`no pressable ${testID}`);
    act(() => node.props.onPress());
  };
  const pressAny = () => {
    const node = tree.root.findAll((n) => typeof n.props?.onPress === 'function', { deep: true })[0];
    if (node) act(() => node.props.onPress());
  };
  return { tree, json, press, pressAny, unmount: () => act(() => tree.unmount()) };
}

