/**
 * The PROP VARIANTS — every widget below is drawn two ways by real designs,
 * and only one way was ever rendered by a test.
 *
 * These are not padding. A design that measures its own tab widths, or asks for
 * an underline instead of a pill, or puts the currency symbol after the amount,
 * takes a different branch through the same component. Each of those branches
 * is a place a layout can be wrong for one app while every other app is fine.
 */
/**
 * A tab's resolved flexBasis, 0 when it is sharing the row equally.
 *
 * Scans EVERY node carrying the testID, not the first: a composite element and
 * the host View it renders both answer to it, and only one of them has a style.
 */
function tabBasis(tree: renderer.ReactTestRenderer, testID: string): number {
  for (const node of tree.root.findAll((n) => n.props?.testID === testID, { deep: true })) {
    const basis = (node.props?.style as { flexBasis?: number } | undefined)?.flexBasis;
    if (typeof basis === 'number') return basis;
  }
  return 0;
}

function byLabel(tree: renderer.ReactTestRenderer, label: string) {
  const node = tree.root.findAll(
    (n) => n.props?.accessibilityLabel === label && typeof n.props?.onPress === 'function',
    { deep: true },
  )[0];
  if (!node) throw new Error('no pressable labelled ' + label);
  act(() => node.props.onPress());
}

describe('RatingStars', () => {
  const stars = (json: string) => json.split('★').length - 1;
  it('fills up to the ROUNDED value and no further', () => {
    const c = mount(<RatingStars testID="rate" max={5} value={3.4} />);
    expect(stars(c.json)).toBe(5);
    c.unmount();
  });
  it('clamps a value outside the scale instead of drawing extra stars', () => {
    const hi = mount(<RatingStars testID="hi" max={4} value={99} />);
    expect(stars(hi.json)).toBe(4);
    hi.unmount();
    const lo = mount(<RatingStars testID="lo" max={4} value={-3} />);
    expect(stars(lo.json)).toBe(4);
    lo.unmount();
  });
  it('reports the ONE-BASED score when editable, and is inert otherwise', () => {
    const onChange = jest.fn();
    const c = mount(<RatingStars testID="rate" max={5} value={0} editable onChange={onChange} />);
    c.press('rate:star:4');
    expect(onChange).toHaveBeenCalledWith(4);
    c.unmount();
    const ro = mount(<RatingStars testID="ro" max={5} value={2} onChange={onChange} />);
    ro.pressAny();
    expect(onChange).toHaveBeenCalledTimes(1);
    ro.unmount();
  });
  it('draws the design ART when given, at the measured icon box', () => {
    const c = mount(
      <RatingStars testID="rate" max={3} value={2} starSize={40} gap={6}
        iconWidth={28} iconHeight={26} emptyOpacity={0.5}
        filledAsset={{ uri: 'on.png' }} emptyAsset={{ uri: 'off.png' }} />,
    );
    expect(c.json).toContain('on.png');
    expect(c.json).toContain('off.png');
    expect(c.json).toContain('28');
    c.unmount();
  });
});

describe('AppModal', () => {
  const child = <Checkbox testID="inner" label="L" value={false} onChange={() => undefined} />;
  it('closes on the backdrop, in both variants', () => {
    for (const variant of ['center', 'sheet'] as const) {
      const onClose = jest.fn();
      const c = mount(<AppModal visible variant={variant} onClose={onClose} testID="m">{child}</AppModal>);
      c.press('modal-backdrop');
      expect(onClose).toHaveBeenCalled();
      c.unmount();
    }
  });
  it('renders a designed sheet at its MEASURED frame, not float-centered', () => {
    const c = mount(
      <AppModal visible variant="sheet" onClose={() => undefined} panelLeft={0} panelTop={220} testID="panel">
        {child}
      </AppModal>,
    );
    expect(c.json).toContain('220');
    expect(c.json).toContain('absolute');
    c.unmount();
  });
  it('hands the flow to the platform Modal when the design asks for a NATIVE one', () => {
    const c = mount(<AppModal visible native variant="sheet" onClose={() => undefined} testID="n">{child}</AppModal>);
    expect(c.json).toContain('inner');
    c.unmount();
  });
  it('takes the hardware back button while open, and answers it as HANDLED', () => {
    const onClose = jest.fn();
    const spy = jest.spyOn(BackHandler, 'addEventListener');
    const c = mount(<AppModal visible onClose={onClose} testID="m">{child}</AppModal>);
    const call = spy.mock.calls[0];
    expect(call?.[0]).toBe('hardwareBackPress');
    // true = "I consumed it". Returning false would close the modal AND pop the
    // screen behind it, which is the bug this handler exists to prevent.
    expect((call?.[1] as () => boolean)()).toBe(true);
    expect(onClose).toHaveBeenCalled();
    c.unmount();
    spy.mockRestore();
  });
  it('does NOT take hardware back when closed, or when the native Modal owns it', () => {
    const spy = jest.spyOn(BackHandler, 'addEventListener');
    const a = mount(<AppModal visible={false} onClose={() => undefined} testID="a">{child}</AppModal>);
    const b = mount(<AppModal visible native onClose={() => undefined} testID="b">{child}</AppModal>);
    expect(spy).not.toHaveBeenCalled();
    a.unmount(); b.unmount();
    spy.mockRestore();
  });
});

describe('SegmentedControl variants', () => {
  const OPTS = ['One', 'Two', 'Three'];
  it('honours the design MEASURED tab widths when it gave one per option', () => {
    const c = mount(
      <SegmentedControl testID="seg" options={OPTS} activeIndex={0} onChange={() => undefined}
        optionWidths={[100, 90, 120]} />,
    );
    // the widths reach flexBasis through s(), so assert the design's
    // PROPORTIONS survived rather than the raw pixel numbers
    const basis = OPTS.map((_, i) => tabBasis(c.tree, 'seg:' + i));
    expect(basis[1]).toBeLessThan(basis[0] as number);
    expect(basis[0]).toBeLessThan(basis[2] as number);
    c.unmount();
  });
  it('lets every tab share the row equally when the design measured none', () => {
    const c = mount(
      <SegmentedControl testID="seg" options={OPTS} activeIndex={0} onChange={() => undefined} />,
    );
    expect(OPTS.map((_, i) => tabBasis(c.tree, 'seg:' + i))).toEqual([0, 0, 0]);
    c.unmount();
  });
  it('IGNORES a partial or zero-width set rather than collapsing a tab', () => {
    for (const optionWidths of [[100, 90], [100, 0, 120]]) {
      const c = mount(
        <SegmentedControl testID="seg" options={OPTS} activeIndex={1} onChange={() => undefined}
          optionWidths={optionWidths} />,
      );
      expect(c.json).toContain('Three');
      c.unmount();
    }
  });
  it('inks the active label white on a pill and keeps the label colour on an underline', () => {
    const pill = mount(
      <SegmentedControl testID="p" options={OPTS} activeIndex={0} onChange={() => undefined}
        indicator="pill" labelColor="#123456" />,
    );
    expect(pill.json).toContain('#ffffff');
    pill.unmount();
    const und = mount(
      <SegmentedControl testID="u" options={OPTS} activeIndex={0} onChange={() => undefined}
        indicator="underline" labelColor="#123456" />,
    );
    expect(und.json).toContain('#123456');
    expect(und.json).not.toContain('#ffffff');
    und.unmount();
  });
  it('reports the pressed tab by INDEX', () => {
    const onChange = jest.fn();
    const c = mount(
      <SegmentedControl testID="seg" options={OPTS} activeIndex={0} onChange={onChange}
        activeTextColor="#000" itemRadius={8} />,
    );
    c.pressAny();
    expect(onChange).toHaveBeenCalledWith(expect.any(Number));
    c.unmount();
  });
});

describe('MonthCalendar variants', () => {
  it('rolls the YEAR at both ends of the grid, not just the month', () => {
    const jan = mount(<MonthCalendar testID="cal" initialDate="2026-01-15" onChange={() => undefined} />);
    expect(jan.json).toContain('2026');
    byLabel(jan.tree, 'Previous month');
    expect(JSON.stringify(jan.tree.toJSON())).toContain('2025');
    jan.unmount();
    const dec = mount(<MonthCalendar testID="cal" initialDate="2026-12-10" onChange={() => undefined} />);
    byLabel(dec.tree, 'Next month');
    expect(JSON.stringify(dec.tree.toJSON())).toContain('2027');
    dec.unmount();
  });
  // The year arrows belong to the POPUP (a date of birth, with Cancel): the
  // inline calendar draws none, because its design does not. This case
  // mounted the inline one and could never find them, which left every
  // generated suite red — and CI does not scan an app whose tests fail.
  it('steps a whole YEAR in the popup (a date of birth); the inline calendar has no year arrows', () => {
    const c = mount(
      <MonthCalendar testID="cal" initialDate="2026-06-01" onChange={() => undefined} onCancel={() => undefined} />,
    );
    byLabel(c.tree, 'Previous year');
    expect(JSON.stringify(c.tree.toJSON())).toContain('2025');
    byLabel(c.tree, 'Next year');
    expect(JSON.stringify(c.tree.toJSON())).toContain('2026');
    c.unmount();
    const inline = mount(<MonthCalendar testID="cal" initialDate="2026-06-01" onChange={() => undefined} />);
    expect(() => byLabel(inline.tree, 'Previous year')).toThrow('no pressable labelled');
    inline.unmount();
  });
  it('offsets the grid when the design starts its week on MONDAY', () => {
    const sun = mount(
      <MonthCalendar testID="a" initialDate="2026-03-01" onChange={() => undefined}
        weekStart="sunday" weekdayLabels={['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa']} />,
    );
    const mon = mount(
      <MonthCalendar testID="b" initialDate="2026-03-01" onChange={() => undefined}
        weekStart="monday" weekdayLabels={['Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa', 'Su']} />,
    );
    expect(mon.json).toContain('Mo');
    expect(mon.json).not.toBe(sun.json);
    sun.unmount(); mon.unmount();
  });
  it('draws the LEFT-aligned header the design measured, with its own card skin', () => {
    const c = mount(
      <MonthCalendar testID="cal" initialDate="2026-03-01" onChange={() => undefined}
        headerAlign="left" headerFontSize={18} cardColor="#ffffff" cardRadius={12}
        weekdayColor="#334455" weekdayBg="#eeeeff" weekdayBgRadius={6} />,
    );
    expect(c.json).toContain('#eeeeff');
    expect(c.json).toContain('18');
    c.unmount();
  });
  it('shades a RANGE between two chosen days', () => {
    const c = mount(
      <MonthCalendar testID="cal" initialDate="2026-03-01" onChange={() => undefined}
        rangeStart={5} rangeEnd={12} rangeBg="#dfe8ff" selectedDay={5} />,
    );
    expect(c.json).toContain('#dfe8ff');
    c.unmount();
  });
  it('reports the pressed day as an ISO date', () => {
    const onChange = jest.fn();
    const c = mount(<MonthCalendar testID="cal" initialDate="2026-03-01" onChange={onChange} />);
    c.press('cal:day:14');
    expect(onChange).toHaveBeenCalledWith('2026-03-14');
    c.unmount();
  });
});

